1494	+/// <summary>Stores every DateTime as UTC and reads it back with Kind = Utc (AD-9).</summary>
1495	+public sealed class UtcDateTimeConverter : ValueConverter<DateTime, DateTime>
1496	+{
1497	+    public UtcDateTimeConverter()
1498	+        : base(v => ToUtc(v), v => DateTime.SpecifyKind(v, DateTimeKind.Utc))
1499	+    {
1500	+    }
1501	+
1502	+    private static DateTime ToUtc(DateTime value) => value.Kind switch
1503	+    {
1504	+        DateTimeKind.Utc => value,
1505	+        DateTimeKind.Local => value.ToUniversalTime(),
1506	+        _ => DateTime.SpecifyKind(value, DateTimeKind.Utc),
1507	+    };
1508	+}
