2042	+using Microsoft.AspNetCore.Diagnostics;
2043	+
2044	+namespace Meridian.Web.Api;
2045	+
2046	+/// <summary>Turns malformed request bodies (e.g. invalid JSON) into 400 problem details instead of 500.</summary>
2047	+internal sealed class BadRequestExceptionHandler : IExceptionHandler
2048	+{
2049	+    private readonly IProblemDetailsService _problemDetails;
2050	+
2051	+    public BadRequestExceptionHandler(IProblemDetailsService problemDetails)
2052	+    {
2053	+        _problemDetails = problemDetails;
2054	+    }
2055	+
2056	+    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
2057	+    {
2058	+        if (exception is not BadHttpRequestException badRequest)
2059	+        {
2060	+            return false;
2061	+        }
2062	+
2063	+        httpContext.Response.StatusCode = badRequest.StatusCode;
2064	+        return await _problemDetails.TryWriteAsync(new ProblemDetailsContext
2065	+        {
2066	+            HttpContext = httpContext,
2067	+            Exception = exception,
2068	+            ProblemDetails =
2069	+            {
2070	+                Status = badRequest.StatusCode,
2071	+                Title = "The request body could not be read.",
2072	+            },
2073	+        });
2074	+    }
2075	+}
